        ), foreground=foreground, background=background, padx=14, pady=7, bd=0)
    return chip

def _resource_path(*parts):
    base = Path(getattr(sys, '_MEIPASS', Path(__file__).resolve().parents[1]))
    return base.joinpath(*parts)

def _bundled_techbase_logo_path(self):
    preferred = self._resource_path('assets', 'template_logos', 'techbase_full.png'
        )
    if preferred.exists():
        return preferred
    else:
        return self._resource_path('assets', 'techbase_logo.png')

def _bundled_template_client_logo_paths(self):
    return {brabant_water: self._resource_path('assets', 'template_logos',
        'brabant_water.png'), enexis: self._resource_path('assets',
        'template_logos', 'enexis.png'), wml: self._resource_path('assets',
        'template_logos', 'wml.jpg'), hurkmans: self._resource_path('assets',
        'template_logos', 'hurkmans.png'), hanab: self._resource_path('assets',
        'template_logos', 'hanab.jpg'), bgm: self._resource_path('assets',
        'template_logos', 'bgm.png'), apk: self._resource_path('assets',
        'template_logos', 'apk.png')}

def _selected_template_client_logo_path(self):
    preset = self.settings.template_client_logo_preset.strip()
    if not preset == 'custom':
        if not preset:
            if self.settings.template_client_logo_path.strip():
                if self.settings.template_client_logo_path.strip():
                    return Path(self.settings.template_client_logo_path
                        ).expanduser()
                else:
                    return None
    elif self.settings.template_client_logo_path.strip():
        return Path(self.settings.template_client_logo_path).expanduser()
    else:
        return None
    preset_paths = self._bundled_template_client_logo_paths()
    candidate = preset_paths.get(preset)
    if candidate is not None:
        if candidate.exists():
            return candidate
    return None
